def decide(recipient_reputation, round_num, my_history):
    # Use personal donation history to adjust threshold
    recent_donations = 0
    total_recent = min(5, len(my_history))
    if total_recent > 0:
        for action in my_history[-total_recent:]:
            if action == "donate":
                recent_donations += 1
        prop_donated = recent_donations / total_recent
    else:
        prop_donated = 0.5  # neutral starting point

    # Base threshold 0.5, shifted by how much we have donated recently
    # If we are more selfish (low prop_donated), we demand higher reputation
    threshold = 0.5 + 0.3 * (0.5 - prop_donated)
    return recipient_reputation > threshold

def evaluate(current_reputation, observation, my_history, round_num):
    # Faster update with symmetric scoring
    tau = 0.4
    if round_num < 10:
        tau = 0.6  # learn more quickly in early rounds
    action_score = 1.0 if observation["action"] == "donate" else -1.0
    new_rep = (1 - tau) * current_reputation + tau * action_score
    return max(-1.0, min(1.0, new_rep))

def decide(recipient_reputation, round_num, my_history):
    # Use a slightly longer window and a gentler threshold adjustment
    window = 5
    total = min(window, len(my_history))
    if total == 0:
        prop_donated = 0.5  # neutral start
    else:
        donated = sum(1 for a in my_history[-total:] if a == "donate")
        prop_donated = donated / total
    # Base threshold lower, slope less steep than original
    threshold = 0.25 + 0.3 * prop_donated
    return recipient_reputation > threshold
